CREATE     PROCEDURE [synapse_fo].[usp_Update_CUSTTRANSOPEN]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:35
	Description: Update stored procedure for CUSTTRANSOPEN from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTNUM] = stg.[ACCOUNTNUM],
		tgt.[AMOUNTCUR] = stg.[AMOUNTCUR],
		tgt.[AMOUNTMST] = stg.[AMOUNTMST],
		tgt.[BANKDISCNOTICEDEADLINE] = stg.[BANKDISCNOTICEDEADLINE],
		tgt.[BANKLCEXPORTLINE] = stg.[BANKLCEXPORTLINE],
		tgt.[CASHDISCDATE] = stg.[CASHDISCDATE],
		tgt.[CASHDISCOUNTLEDGERDIMENSION] = stg.[CASHDISCOUNTLEDGERDIMENSION],
		tgt.[COLLECTIONLETTER] = stg.[COLLECTIONLETTER],
		tgt.[COLLECTIONLETTERCODE] = stg.[COLLECTIONLETTERCODE],
		tgt.[COVSTATUS] = stg.[COVSTATUS],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DUEDATE] = stg.[DUEDATE],
		tgt.[EXCHADJUNREALIZED] = stg.[EXCHADJUNREALIZED],
		tgt.[EXCHADJUNREALIZEDREPORTING] = stg.[EXCHADJUNREALIZEDREPORTING],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FINEAMOUNT_BR] = stg.[FINEAMOUNT_BR],
		tgt.[FINEAMOUNTPAYMCUR_BR] = stg.[FINEAMOUNTPAYMCUR_BR],
		tgt.[FINECODE_BR] = stg.[FINECODE_BR],
		tgt.[INTERESTAMOUNT_BR] = stg.[INTERESTAMOUNT_BR],
		tgt.[INTERESTAMOUNTPAYMCUR_BR] = stg.[INTERESTAMOUNTPAYMCUR_BR],
		tgt.[INTERESTCODE_BR] = stg.[INTERESTCODE_BR],
		tgt.[LASTINTERESTDATE] = stg.[LASTINTERESTDATE],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		--tgt.[LSN] = stg.[LSN],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[POSSIBLECASHDISC] = stg.[POSSIBLECASHDISC],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[REFRECID] = stg.[REFRECID],
		tgt.[REPORTINGCURRENCYAMOUNT] = stg.[REPORTINGCURRENCYAMOUNT],
		tgt.[SETTLEDLINEPERCENT_IN] = stg.[SETTLEDLINEPERCENT_IN],
		tgt.[SETTLEDTOTALAMOUNT_IN] = stg.[SETTLEDTOTALAMOUNT_IN],
		tgt.[SETTLEMENTPRIORITYCASHDISCDATE] = stg.[SETTLEMENTPRIORITYCASHDISCDATE],
		--tgt.[SKS_EPY_SENTTOEPAY] = stg.[SKS_EPY_SENTTOEPAY],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TAXDISTRIBUTION] = stg.[TAXDISTRIBUTION],
		tgt.[TAXWITHHOLDAMOUNTORIGIN_IN] = stg.[TAXWITHHOLDAMOUNTORIGIN_IN],
		tgt.[TCSAMOUNT_IN] = stg.[TCSAMOUNT_IN],
		tgt.[TDSAMOUNT_IN] = stg.[TDSAMOUNT_IN],
		tgt.[TRANSDATE] = stg.[TRANSDATE],
		tgt.[USECASHDISC] = stg.[USECASHDISC]
	 FROM [synapse_fo].[CUSTTRANSOPEN] tgt
		INNER JOIN [staging_fo].[CUSTTRANSOPEN] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
